import { ChangeDetectionStrategy, Component } from '@angular/core';

import { NgIcon, provideIcons } from '@ng-icons/core';
import { lucidePlus } from '@ng-icons/lucide';

import { ZardSidebarImports } from '@zard/components/sidebar/sidebar.imports';

import { Sidebar12CalendarsComponent, type Sidebar12Calendar } from './sidebar-12-calendars.component';
import { Sidebar12DatePickerComponent } from './sidebar-12-date-picker.component';
import { Sidebar12NavUserComponent, type Sidebar12User } from './sidebar-12-nav-user.component';

@Component({
  selector: 'lib-sidebar-12-app-sidebar',
  standalone: true,
  imports: [
    ...ZardSidebarImports,
    Sidebar12NavUserComponent,
    Sidebar12DatePickerComponent,
    Sidebar12CalendarsComponent,
    NgIcon,
  ],
  viewProviders: [provideIcons({ lucidePlus })],
  templateUrl: './sidebar-12-app-sidebar.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: 'contents' },
})
export class Sidebar12AppSidebarComponent {
  // This is sample data.
  protected readonly user: Sidebar12User = {
    name: 'shadcn',
    email: 'm@example.com',
    avatar: 'https://github.com/shadcn.png',
  };

  protected readonly calendars: readonly Sidebar12Calendar[] = [
    { name: 'My Calendars', items: ['Personal', 'Work', 'Family'] },
    { name: 'Favorites', items: ['Holidays', 'Birthdays'] },
    { name: 'Other', items: ['Travel', 'Reminders', 'Deadlines'] },
  ];
}

import { ChangeDetectionStrategy, Component, input } from '@angular/core';

import { NgIcon, provideIcons } from '@ng-icons/core';
import { lucideCheck, lucideChevronRight } from '@ng-icons/lucide';

import { ZardCollapsibleImports } from '@zard/components/collapsible/collapsible.imports';
import { ZardSidebarImports } from '@zard/components/sidebar/sidebar.imports';

export interface Sidebar12Calendar {
  readonly name: string;
  readonly items: readonly string[];
}

@Component({
  selector: 'lib-sidebar-12-calendars',
  standalone: true,
  imports: [...ZardSidebarImports, ...ZardCollapsibleImports, NgIcon],
  viewProviders: [provideIcons({ lucideCheck, lucideChevronRight })],
  templateUrl: './sidebar-12-calendars.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: 'contents' },
})
export class Sidebar12CalendarsComponent {
  readonly calendars = input<readonly Sidebar12Calendar[]>([]);
}

import { ChangeDetectionStrategy, Component } from '@angular/core';

import { ZardCalendarComponent } from '@zard/components/calendar/calendar.component';
import { ZardSidebarImports } from '@zard/components/sidebar/sidebar.imports';

@Component({
  selector: 'lib-sidebar-12-date-picker',
  standalone: true,
  imports: [...ZardSidebarImports, ZardCalendarComponent],
  templateUrl: './sidebar-12-date-picker.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { class: 'contents' },
})
export class Sidebar12DatePickerComponent {}

import { ChangeDetectionStrategy, Component, input } from '@angular/core';

import { NgIcon, provideIcons } from '@ng-icons/core';
import {
  lucideBadgeCheck,
  lucideBell,
  lucideChevronsUpDown,
  lucideCreditCard,
  lucideLogOut,
  lucideSparkles,
} from '@ng-icons/lucide';

import { ZardAvatarComponent } from '@zard/components/avatar/avatar.component';
import { ZardDropdownImports } from '@zard/components/dropdown/dropdown.imports';
import { ZardSidebarImports } from '@zard/components/sidebar/sidebar.imports';

export interface Sidebar12User {
  readonly name: string;
  readonly email: string;
  readonly avatar: string;
}

@Component({
  selector: 'lib-sidebar-12-nav-user',
  standalone: true,
  imports: [...ZardSidebarImports, ...ZardDropdownImports, ZardAvatarComponent, NgIcon],
  viewProviders: [
    provideIcons({
      lucideBadgeCheck,
      lucideBell,
      lucideChevronsUpDown,
      lucideCreditCard,
      lucideLogOut,
      lucideSparkles,
    }),
  ],
  templateUrl: './sidebar-12-nav-user.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class Sidebar12NavUserComponent {
  readonly user = input.required<Sidebar12User>();
}

import { ChangeDetectionStrategy, Component } from '@angular/core';

import { ZardBreadcrumbImports } from '@zard/components/breadcrumb/breadcrumb.imports';
import { ZardSeparatorComponent } from '@zard/components/separator/separator.component';
import { ZardSidebarImports } from '@zard/components/sidebar/sidebar.imports';

import { Sidebar12AppSidebarComponent } from './sidebar-12-app-sidebar.component';

@Component({
  selector: 'lib-sidebar-12',
  standalone: true,
  imports: [...ZardSidebarImports, ...ZardBreadcrumbImports, ZardSeparatorComponent, Sidebar12AppSidebarComponent],
  templateUrl: './sidebar-12.component.html',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class Sidebar12Component {
  protected readonly placeholders = Array.from({ length: 20 }, (_, index) => index);
}
